import React, { useContext, useState, useEffect, useRef } from "react";
import { Table, Input, Button, Popconfirm, Form, Tag } from "antd";
import __t from "translation/translation";
const EditableContext = React.createContext(null);

const EditableRow = ({ index, ...props }) => {
  const [form] = Form.useForm();
  return (
    <Form form={form} component={false}>
      <EditableContext.Provider value={form}>
        <tr {...props} />
      </EditableContext.Provider>
    </Form>
  );
};

const EditableCell = ({
  title,
  editable,
  children,
  dataIndex,
  record,
  handleSave,
  ...restProps
}) => {
  const [editing, setEditing] = useState(false);
  const inputRef = useRef(null);
  const form = useContext(EditableContext);
  useEffect(() => {
    if (editing) {
      inputRef.current.focus();
    }
  }, [editing]);

  const toggleEdit = () => {
    setEditing(!editing);
    form.setFieldsValue({
      [dataIndex]: record[dataIndex],
    });
  };

  const save = async () => {
    try {
      const values = await form.validateFields();
      toggleEdit();
      handleSave({ ...record, ...values });
    } catch (errInfo) {
      console.log("Save failed:", errInfo);
    }
  };

  let childNode = children;

  if (editable) {
    childNode = editing ? (
      <Form.Item
        style={{
          margin: 0,
        }}
        name={dataIndex}
        rules={[
          {
            required: true,
            message: `${title} is required.`,
          },
        ]}
      >
        <Input ref={inputRef} onPressEnter={save} onBlur={save} />
      </Form.Item>
    ) : (
      <div
        className="editable-cell-value-wrap"
        style={{
          paddingRight: 24,
        }}
        onClick={toggleEdit}
      >
        {children}
      </div>
    );
  }

  return <td {...restProps}>{childNode}</td>;
};

class CustomEditableTableFactor extends React.Component {
  constructor(props) {
    super(props);
    this.columns = [
      {
        title: __t("row"),
        width: "7%",
        align: "center",
        render: (text, record, index) => (
          <span>
            {text.row}
            <Popconfirm
              title={__t("Sure to delete?")}
              onConfirm={() => this.handleDelete(record.key)}
              className="noPrint"
            >
              <Tag color="red">D</Tag>
            </Popconfirm>
          </span>
        ),
      },
      {
        title: __t("description"),
        dataIndex: "description",
        width: "38%",
        editable: true,
      },
      {
        title: __t("amount"),
        dataIndex: "amount",
        width: "5%",
        editable: true,
      },
      {
        title: __t("unit"),
        dataIndex: "unit",
        width: "15%",
        editable: true,
      },
      {
        title: __t("fee"),
        dataIndex: "fee",
        width: "15%",
        editable: true,
      },
      {
        title: __t("total"),
        dataIndex: "total",
        width: "20%",
        editable: true,
      },
      // {
      //   title: "D",
      //   dataIndex: "operation",
      //   render: (_, record) =>
      //     this.state.dataSource.length >= 1 ? (
      //       <Popconfirm
      //         title="Sure to delete?"
      //         onConfirm={() => this.handleDelete(record.key)}
      //         className="noPrint"
      //       >
      //         <a>D</a>
      //       </Popconfirm>
      //     ) : null,
      // },
    ];
    this.state = {
      dataSource: [
        {
          key: "1",
          row: "1",
          code: "4 1 01 01 0006",
          description: "بتن۳۵۰",
          amount: "1",
          unit: "متر مکعب",
          fee: "6,000,000",
          total: "6,000,000",
        },
      ],
      count: 1,
    };
  }

  handleDelete = (key) => {
    const dataSource = [...this.state.dataSource];
    this.setState({
      dataSource: dataSource.filter((item) => item.key !== key),
    });
  };
  handleAdd = () => {
    const { count, dataSource } = this.state;
    const newData = {
      key: count + 1,
      row: count + 1,
      code: "4 1 01 01 0006",
      description: "بتن۳۵۰",
      amount: "1",
      unit: "متر مکعب",
      fee: "6,000,000",
      total: "6,000,000",
    };
    this.setState({
      dataSource: [...dataSource, newData],
      count: count + 1,
    });
  };
  handleSave = (row) => {
    const newData = [...this.state.dataSource];
    const index = newData.findIndex((item) => row.key === item.key);
    const item = newData[index];
    newData.splice(index, 1, { ...item, ...row });
    this.setState({
      dataSource: newData,
    });
  };

  render() {
    const { dataSource } = this.state;
    const components = {
      body: {
        row: EditableRow,
        cell: EditableCell,
      },
    };
    const columns = this.columns.map((col) => {
      if (!col.editable) {
        return col;
      }

      return {
        ...col,
        onCell: (record) => ({
          record,
          editable: col.editable,
          dataIndex: col.dataIndex,
          title: col.title,
          handleSave: this.handleSave,
        }),
      };
    });
    return (
      <div>
        <Button onClick={this.handleAdd} type="primary" className="noPrint">
          اضافه کردن سطر
        </Button>
        <Table
          components={components}
          rowClassName={() => "editable-row"}
          bordered
          dataSource={dataSource}
          columns={columns}
          pagination={false}
        />
      </div>
    );
  }
}

export default CustomEditableTableFactor;
