import React, { useContext, useState, useEffect, useRef } from "react";
import { Table, Input, Button, Popconfirm, Form, Tag } from "antd";
import __t from "translation/translation";
const EditableContext = React.createContext(null);

const EditableRow = ({ index, ...props }) => {
  const [form] = Form.useForm();
  return (
    <Form form={form} component={false}>
      <EditableContext.Provider value={form}>
        <tr {...props} />
      </EditableContext.Provider>
    </Form>
  );
};

const EditableCell = ({
  title,
  editable,
  children,
  dataIndex,
  record,
  handleSave,
  ...restProps
}) => {
  const [editing, setEditing] = useState(false);
  const inputRef = useRef(null);
  const form = useContext(EditableContext);
  useEffect(() => {
    if (editing) {
      inputRef.current.focus();
    }
  }, [editing]);

  const toggleEdit = () => {
    setEditing(!editing);
    form.setFieldsValue({
      [dataIndex]: record[dataIndex],
    });
  };

  const save = async () => {
    try {
      const values = await form.validateFields();
      toggleEdit();
      handleSave({ ...record, ...values });
    } catch (errInfo) {
      console.log("Save failed:", errInfo);
    }
  };

  let childNode = children;

  if (editable) {
    childNode = editing ? (
      <Form.Item
        style={{
          margin: 0,
        }}
        name={dataIndex}
        rules={[
          {
            required: true,
            message: `${title} is required.`,
          },
        ]}
      >
        <Input ref={inputRef} onPressEnter={save} onBlur={save} />
      </Form.Item>
    ) : (
      <div
        className="editable-cell-value-wrap"
        style={{
          paddingRight: 24,
        }}
        onClick={toggleEdit}
      >
        {children}
      </div>
    );
  }

  return <td {...restProps}>{childNode}</td>;
};

class CustomEditableTableBill extends React.Component {
  constructor(props) {
    super(props);
    this.columns = [
      {
        title: __t("row"),
        width: "5%",
        align: "center",
        render: (text, record, index) => (
          <span>
            {text.row}
            <Popconfirm
              title={__t("Sure to delete?")}
              onConfirm={() => this.handleDelete(record.key)}
              className="noPrint"
            >
              <Tag color="red">D</Tag>
            </Popconfirm>
          </span>
        ),
      },
      {
        title: "تاریخ",
        dataIndex: "date",
        width: "11%",
        editable: true,
      },
      {
        title: "شماره سند",
        dataIndex: "code",
        width: "9%",
        editable: true,
      },
      {
        title: "شرح",
        dataIndex: "description",
        width: "37%",
        editable: true,
      },
      {
        title: "بدهکار",
        dataIndex: "bedehkar",
        width: "11%",
        editable: true,
      },
      {
        title: "بستانکار",
        dataIndex: "besankar",
        width: "11%",
        editable: true,
      },
      {
        title: "مانده",
        dataIndex: "mandeh",
        width: "11%",
        editable: true,
      },
      {
        title: "تش",
        dataIndex: "tash",
        width: "5%",
        editable: true,
      },
    ];
    this.state = {
      dataSource: [
        {
          key: "1",
          row: "1",
          date: "1400/06/01",
          code: "342",
          description: "دریافت چک",
          bedehkar: "0",
          besankar: "310،000،000",
          mandeh: "20،564،000",
          tash: "بس",
        },
      ],
      count: 1,
    };
  }

  handleDelete = (key) => {
    const dataSource = [...this.state.dataSource];
    this.setState({
      dataSource: dataSource.filter((item) => item.key !== key),
      count: key - 1,
    });
  };
  handleAdd = () => {
    const { count, dataSource } = this.state;
    const newData = {
      key: count + 1,
      row: count + 1,
      date: "1400/06/01",
      code: "342",
      description: "دریافت چک",
      bedehkar: "0",
      besankar: "310،000،000",
      mandeh: "20،564،000",
      tash: "بس",
    };
    this.setState({
      dataSource: [...dataSource, newData],
      count: count + 1,
    });
  };
  handleTotal = () => {
    const { count, dataSource } = this.state;
    const newData = {
      key: count + 1,
      row: "",
      date: "",
      code: "",
      description: "جمع :",
      bedehkar: "0",
      besankar: "310،000،000",
      mandeh: "20،564،000",
      tash: "بس",
    };
    this.setState({
      dataSource: [...dataSource, newData],
    });
  };
  handleSave = (row) => {
    const newData = [...this.state.dataSource];
    const index = newData.findIndex((item) => row.key === item.key);
    const item = newData[index];
    newData.splice(index, 1, { ...item, ...row });
    this.setState({
      dataSource: newData,
    });
  };

  render() {
    const { dataSource } = this.state;
    const components = {
      body: {
        row: EditableRow,
        cell: EditableCell,
      },
    };
    const columns = this.columns.map((col) => {
      if (!col.editable) {
        return col;
      }

      return {
        ...col,
        onCell: (record) => ({
          record,
          editable: col.editable,
          dataIndex: col.dataIndex,
          title: col.title,
          handleSave: this.handleSave,
        }),
      };
    });
    return (
      <div className="tableBill">
        <Button onClick={this.handleAdd} type="primary" className="noPrint">
          اضافه کردن سطر
        </Button>
        <Button
          onClick={this.handleTotal}
          style={{ marginRight: "8px" }}
          type="primary"
          className="noPrint"
        >
          اضافه کردن جمع
        </Button>
        <Table
          components={components}
          rowClassName={() => "editable-row"}
          bordered
          dataSource={dataSource}
          columns={columns}
          pagination={false}
        />
      </div>
    );
  }
}

export default CustomEditableTableBill;
