import { createIntl } from "react-intl";

import en_message from "./locales/en.json";
import fa_message from "./locales/fa.json";

// Translate Function
const __t = (str, values) => {
  let locale = localStorage.getItem("language") || "FA";
  let intl = {};

  switch (locale.toUpperCase()) {
    case "FA":
      intl = createIntl({ messages: fa_message, locale });
      break;
    case "EN":
      intl = createIntl({ messages: en_message, locale });
      break;
    default:
      intl = createIntl({ messages: fa_message, locale: "FA" });
      break;
  }

  return intl.formatMessage(
    {
      id: str,
      defaultMessage: str
    },
    values
  );
};

export default __t;
