import React, { useContext } from "react";
import __t from "translation/translation";
import { Button } from "antd";
import CustomInputLabel from "components/CustomInput";
import CustomEditableTableBill from "components/CustomEditableTableBill";

const Dashboard = (props) => {
  const print = () => {
    window.print();
  };
  return (
    <div className="print">
      <Button type="primary" onClick={print} className="noPrint chap">
        {__t("Print")}
      </Button>

      <div className="wrapperA4">
        <div className="titleHead">
          <CustomInputLabel
            fontWeight="bold"
            defaultValue="سال مالی 1400"
            width="100%"
            textAlign="center"
          />
        </div>
        <div className="subtitleHead">
          <CustomInputLabel
            defaultValue="صورت ریز عملیات حساب"
            fontWeight="bold"
            width="100%"
            textAlign="center"
          />
        </div>
        <div>
          <CustomInputLabel defaultValue="مشخصات گزارش:" width="200px" />
        </div>
        <div style={{ marginRight: "20px" }}>
          <CustomInputLabel label="از تاریخ:" width="90px" />
          <CustomInputLabel label="تا تاریخ:" width="90px" />
        </div>
        <div style={{ marginRight: "20px" }}>
          <CustomInputLabel label="حساب:" width="80%" />
        </div>
        <div className="contentBoxBillWrapper">
          <div className="contentBoxBill">
            <CustomEditableTableBill />
          </div>
          <div className="timeBill">
            <div>
              <CustomInputLabel label="زمان تهیه گزارش :" width="300px" />
            </div>
            <div>
              <CustomInputLabel label="صفحه :" defaultValue="1" width="25px" />
              <CustomInputLabel label="از :" defaultValue="1" width="25px" />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
