import React, { useState } from "react";
import LanguageContext from "context/LanguageContext";
import { ConfigProvider } from "antd";
import MainLayout from "layout/MainLayout";

const App = (props) => {
  const [language, setLanguage] = useState(
    localStorage.getItem("language") || "FA"
  );
  document.body.classList.add("lang-" + language);

  const toggleLanguage = () => {
    if (language === "FA") {
      setLanguage("EN");
      window.localStorage.setItem("language", "EN");
      document.body.classList.remove("lang-" + language);
      document.body.classList.add("lang-" + "EN");
    } else {
      setLanguage("FA");
      window.localStorage.setItem("language", "FA");
      document.body.classList.remove("lang-" + language);
      document.body.classList.add("lang-" + "FA");
    }
    // window.location.reload();
  };
  return (
    <>
      <LanguageContext.Provider value={{ toggleLanguage, language }}>
        <ConfigProvider direction={language === "FA" ? "rtl" : "ltr"}>
          <MainLayout />
        </ConfigProvider>
      </LanguageContext.Provider>
    </>
  );
};

export default App;
