import React, { useState, useContext } from "react";
import LanguageContext from "context/LanguageContext";
import __t from "translation/translation";
import { Layout, Button } from "antd";
import MenuUnfoldOutlined from "@ant-design/icons/es/icons/MenuUnfoldOutlined";
import MenuFoldOutlined from "@ant-design/icons/es/icons/MenuFoldOutlined";
const { Header } = Layout;

const MainLayout = (props) => {
  const { toggle, collapsed } = props;
  const { toggleLanguage, language } = useContext(LanguageContext);
  return (
    <Header className="header" className="noPrint">
      <span onClick={toggle} className="trigger">
        {collapsed ? <MenuFoldOutlined /> : <MenuUnfoldOutlined />}
      </span>
      <span className="language">
        {__t("language")}
        <Button type="primary" onClick={toggleLanguage}>
          {language === "FA" ? "EN" : "FA"}
        </Button>
      </span>
    </Header>
  );
};

export default MainLayout;
