import React from "react";
import { Input } from "antd";
import __t from "translation/translation";

const CustomInput = (props) => {
  const {
    label,
    bordered = false,
    fontWeight = "normal",
    fontSize,
    defaultValue,
    textAlign = "right",
    width = "50px",
    bgColor = "#fff",
  } = props;

  return (
    <>
      {!!label && <span>{label}</span>}
      <Input
        bordered={bordered}
        defaultValue={defaultValue}
        style={{
          width: width,
          fontWeight: fontWeight,
          fontSize: fontSize,
          textAlign: textAlign,
          backgroundColor: bgColor,
        }}
      />
    </>
  );
};

export default CustomInput;
